def omp(F,names,k=6):
    sel=[];out=None
    for step in range(k):
        bestk=None
        for j in range(F.shape[1]):
            if j in sel: continue
            A=np.column_stack([F[:,sel+[j]],np.ones_like(t)])
            c,_,_,_=np.linalg.lstsq(A,dv_dt,rcond=None)
            rr=np.mean((dv_dt-A@c)**2)
            if bestk is None or rr<bestk[0]: bestk=(rr,j,c)
        sel.append(bestk[1]); out=bestk
    return 1-out[0]/np.var(dv_dt),[names[s] for s in sel],out[2].round(3)
